import React from 'react';

import { useNavigate } from 'react-router-dom';
import { Link } from 'react-router-dom';

import { HikingBadgeOneLine } from '@apps/Hiking/@components/HikingBadge';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { getEmptyWorkoutTarget } from '../@mappers/workouts.empty';
import { getOneWorkoutTargetById } from '../@services/workoutsTargets.service';
import { IWorkoutTarget } from '../@types/workoutsTargets.types';
import WorkoutTargetForm from '../components/WorkoutTargets/WorkoutTargetForm';
import WorkoutTargetMembers from '../components/WorkoutTargets/WorkoutTargetMembers';
import WorkoutTargetStat from '../components/WorkoutTargets/WorkoutTargetStat';

interface IWorkoutTargetsOnePageProps {
  id_workout_target: number;
}

const WorkoutTargetsOnePage: React.FC<IWorkoutTargetsOnePageProps> = ({ id_workout_target }) => {
  const [data, setData] = React.useState<IWorkoutTarget>();
  const [isLoading, setIsLoading] = React.useState(true);
  const [isEdit, setIsEdit] = React.useState(false);
  const [err, setErr] = React.useState<Error>();

  const authContext = React.useContext(AuthContext);
  const navigate = useNavigate();

  const fetchData = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const d1 = await getOneWorkoutTargetById(id_workout_target);
      setData(d1);
    } catch (error) {
      setErr(error as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_workout_target]);

  React.useEffect(() => {
    if (id_workout_target === 0) {
      authContext.user && setData(getEmptyWorkoutTarget(authContext.user));
      setIsLoading(false);
      return;
    }

    fetchData();
  }, [id_workout_target]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!data)
    return (
      <PohAlert variant={AlertVariant.Warning}>Просмотр цели недоступен. Ошибка доступа</PohAlert>
    );

  return (
    <section>
      <>
        <Breadcrumb
          data={[
            { href: `/workouts`, text: 'Тренировки' },
            { href: `/workouts/targets`, text: 'Цели' },
            { href: `/workouts/targets/${id_workout_target}`, text: data.name, active: true },
          ]}
        />
        <PohContainer>
          <PageHeader title={data.id === 0 ? 'Создание цели тренировок' : data.name}>
            {data.id > 0 && authContext.user?.id === data.author.id && !isEdit && (
              <PohButton
                size={ButtonSize.Small}
                variant={ButtonVariant.Success}
                onClick={() => setIsEdit(true)}
              >
                Редактировать
              </PohButton>
            )}
          </PageHeader>
          {data.hiking && (
            <Link to={`/hiking/${data.hiking.id}`}>
              <HikingBadgeOneLine hiking={data.hiking} className="mt-n2" />
            </Link>
          )}
          {!data.hiking && data.id > 0 && <WorkoutTargetMembers data={data} onJoined={fetchData} />}
          <PohRow>
            <PohCol sm={12}>
              {data.id > 0 && !isEdit ? (
                <WorkoutTargetStat workoutTarget={data} />
              ) : (
                <WorkoutTargetForm
                  data={data}
                  onSave={(up) => {
                    setData(up);
                    setIsEdit(false);
                  }}
                  onCancel={() => {
                    setIsEdit(false);
                    if (data.id === 0) navigate('/workouts/targets');
                  }}
                  onDelete={() => {
                    navigate('/workouts/targets');
                  }}
                />
              )}
            </PohCol>
          </PohRow>
        </PohContainer>
      </>
    </section>
  );
};

export default WorkoutTargetsOnePage;
